<?php
require 'db.php';
$vehicle_id=(int)($_GET['vehicle']??$_POST['vehicle_id']??0);
$stmt=$conn->prepare('SELECT * FROM vehicles WHERE id=?'); $stmt->bind_param('i',$vehicle_id); $stmt->execute(); $vehicle=$stmt->get_result()->fetch_assoc();
if(!$vehicle) die('Vehicle not found. Please go back and choose a vehicle.');
$error=''; $bill=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
  $name=trim($_POST['customer_name']??''); $phone=trim($_POST['phone']??''); $email=trim($_POST['email']??''); $start=$_POST['start_date']??''; $end=$_POST['end_date']??'';
  if($name===''||!preg_match('/^[0-9]{10}$/',$phone)||!filter_var($email,FILTER_VALIDATE_EMAIL)||$start===''||$end==='') $error='Please enter all details correctly.';
  else { try { $s=new DateTime($start); $e=new DateTime($end); if($e<$s) throw new Exception('End date must be after start date.'); $days=$s->diff($e)->days+1; $total=$days*(int)$vehicle['price_per_day']; $ins=$conn->prepare('INSERT INTO bookings (vehicle_id,customer_name,phone,email,start_date,end_date,total_amount) VALUES (?,?,?,?,?,?,?)'); $ins->bind_param('isssssi',$vehicle_id,$name,$phone,$email,$start,$end,$total); if(!$ins->execute()) throw new Exception('Booking could not be saved.'); $bill=['id'=>$ins->insert_id,'name'=>$name,'phone'=>$phone,'email'=>$email,'start'=>$start,'end'=>$end,'days'=>$days,'rate'=>$vehicle['price_per_day'],'total'=>$total]; } catch(Exception $ex){$error=$ex->getMessage();} }
}
$today=date('Y-m-d');
$upi='2205.stkabirnrnp@okicici'; $upi_link='upi://pay?pa='.rawurlencode($upi).'&pn='.rawurlencode('Kalash Shah').'&cu=INR'.($bill?'&am='.rawurlencode(number_format($bill['total'],2,'.','')).'&tn='.rawurlencode('Vehicle Rental Booking #'.$bill['id']):'');
?>
