<header class="site-header"><div class="nav-inner"><a class="brand" href="index.php"><span class="brand-mark">VR</span><span class="brand-name">Vehicle<span>Rental</span></span></a><nav class="main-nav"><a href="index.php">Home</a><a href="vehicles.php">Vehicles</a><a href="about.php">About</a></nav><a class="header-cta" href="vehicles.php">Book a Vehicle <span>→</span></a></div></header>
<section class="booking-page"><div class="booking-wrap"><div class="booking-card"><img class="booking-photo" src="<?= htmlspecialchars($vehicle['image']) ?>" alt="<?= htmlspecialchars($vehicle['vehicle_name']) ?>"><h1>Book <?= htmlspecialchars($vehicle['vehicle_name']) ?></h1><p class="rate">₹<?= number_format($vehicle['price_per_day']) ?> / day</p>
<?php if($error): ?><div class="error"><?= htmlspecialchars($error) ?></div><?php endif; ?>
<?php if(!$bill): ?><form method="post" id="bookingForm" onsubmit="return validateBooking()"><input type="hidden" name="vehicle_id" value="<?= $vehicle_id ?>"><label>Customer Name</label><input name="customer_name" id="customer_name" required><label>Phone Number</label><input name="phone" id="phone" maxlength="10" required><label>Email</label><input type="email" name="email" id="email" required><div class="two"><div><label>Start Date</label><input type="date" name="start_date" id="start_date" min="<?= $today ?>" required></div><div><label>End Date</label><input type="date" name="end_date" id="end_date" min="<?= $today ?>" required></div></div><div id="liveBill" class="bill-preview">Select both dates to calculate your bill.</div><button class="btn full" type="submit">Confirm Booking & Show Bill</button></form>
<?php else: ?><div class="bill"><h2>Booking Bill</h2><div class="bill-grid"><p><b>Booking ID</b><br>#<?= $bill['id'] ?></p><p><b>Customer</b><br><?= htmlspecialchars($bill['name']) ?></p><p><b>Vehicle</b><br><?= htmlspecialchars($vehicle['vehicle_name']) ?></p><p><b>Dates</b><br><?= htmlspecialchars($bill['start']) ?> to <?= htmlspecialchars($bill['end']) ?></p><p><b>Rental Days</b><br><?= $bill['days'] ?></p><p><b>Rate / Day</b><br>₹<?= number_format($bill['rate']) ?></p></div><div class="total">Total Amount: ₹<?= number_format($bill['total']) ?></div><button class="pay-btn" onclick="showQR()">Pay ₹<?= number_format($bill['total']) ?></button><div id="qrBox" class="qr-box hidden"><h2>Scan & Pay</h2><img src="qr_code.png" alt="UPI QR Code"><p><b>Kalash Shah</b></p><p>UPI: <?= htmlspecialchars($upi) ?></p><a class="upi-btn" href="<?= htmlspecialchars($upi_link) ?>">Open UPI App</a><div class="payment-done"><b>Completed your payment?</b><br><button type="button" class="btn confirm-button" id="confirmPaymentBtn" onclick="confirmPayment(); return false;">I Have Paid — Show Confirmation</button></div><div class="booking-confirmed" id="bookingConfirmation"><div class="confirm-icon">✓</div><div><h3>Booking Confirmed</h3><p>Your booking has been successfully confirmed.</p><p><b>Booking ID:</b> #<?= $bill['id'] ?> &nbsp; | &nbsp; <b>Vehicle:</b> <?= htmlspecialchars($vehicle['vehicle_name']) ?></p><p><b>Customer:</b> <?= htmlspecialchars($bill['name']) ?></p><p><b>Rental Period:</b> <?= htmlspecialchars($bill['start']) ?> to <?= htmlspecialchars($bill['end']) ?></p><p class="confirm-total">Total Paid: ₹<?= number_format($bill['total']) ?></p></div></div></div></div><?php endif; ?></div></section>
